SELECT "sk_companyid", "fi_year", "fi_qtr", "fi_qtr_start_date", "fi_revenue", "fi_net_earn", "fi_basic_eps", "fi_dilut_eps", "fi_margin", "fi_inventory", "fi_assets", "fi_liability", "fi_out_basic", "fi_out_dilut" FROM (SELECT TRY_CAST((CAST(HASH(fin.CoNameOrCIK) % 2147483648 AS INT)) AS INT) AS "sk_companyid", TRY_CAST((TRY_CAST(fin.Year AS DECIMAL(4))) AS DECIMAL(4)) AS "fi_year", TRY_CAST((TRY_CAST(fin.Quarter AS DECIMAL(1))) AS DECIMAL(1)) AS "fi_qtr", TRY_CAST((CAST(STRPTIME(fin.QtrStartDate, '%Y%m%d') AS DATE)) AS DATE) AS "fi_qtr_start_date", TRY_CAST((TRY_CAST(fin.Revenue AS DECIMAL(15, 2))) AS DECIMAL(15, 2)) AS "fi_revenue", TRY_CAST((CAST(fin.Earnings AS DECIMAL(15, 2))) AS DECIMAL(15, 2)) AS "fi_net_earn", TRY_CAST((COALESCE(CAST(fin.EPS AS DECIMAL(10, 2)), CAST(0 AS DECIMAL(10, 2)))) AS DECIMAL(10, 2)) AS "fi_basic_eps", TRY_CAST((CAST(fin.DilutedEPS AS DECIMAL(10, 2))) AS DECIMAL(10, 2)) AS "fi_dilut_eps", TRY_CAST((CAST(COALESCE(CAST(fin.Earnings AS DECIMAL(15, 4)) / NULLIF(CAST(fin.Revenue AS DECIMAL(15, 4)), 0), 0) AS DECIMAL(10, 2))) AS DECIMAL(10, 2)) AS "fi_margin", TRY_CAST((CAST(fin.Inventory AS DECIMAL(15, 2))) AS DECIMAL(15, 2)) AS "fi_inventory", TRY_CAST((CAST(fin.Assets AS DECIMAL(15, 2))) AS DECIMAL(15, 2)) AS "fi_assets", TRY_CAST((CAST(fin.Liabilities AS DECIMAL(15, 2))) AS DECIMAL(15, 2)) AS "fi_liability", TRY_CAST((CAST(fin.ShOut AS DECIMAL(12))) AS DECIMAL(12)) AS "fi_out_basic", TRY_CAST((CAST(fin.DilutedShOut AS DECIMAL(12))) AS DECIMAL(12)) AS "fi_out_dilut" FROM "Source"."FinwireFIN" AS fin);
